def _rms(t: torch.Tensor) -> torch.Tensor:
    """Root-mean-square of a tensor as a detached 0-dim float tensor (no host sync)."""
    return t.detach().float().pow(2).mean().sqrt()


class StabilityDiagnosticsCallback(TrainerCallback):
    """Log training-stability signals for deep-model μP diagnosis.

    Registers forward hooks on the unwrapped model to track, on the training-log
    cadence, the signals that separate the failure modes of a deep run:

    * **per-depth residual-stream RMS** — hooked on every ``OplmBlock`` output;
      surfaces residual-stream growth and *which* layer drives it.
    * **per-layer post-QK-norm query/key RMS** — the attention entropy-collapse
      precursor (pre-softmax logits scale with ``‖q‖·‖k‖``); hooked on
      ``attention.q_norm`` / ``attention.k_norm``.
    * **output-logit RMS** — hooked on ``lm_head.decoder``.
    * **global grad norm** — read from ``trainer._last_grad_norm``, captured by
      the trainer at gradient-clip time (absent when ``max_grad_norm <= 0``).

    With ``attention_entropy_every > 0`` it additionally runs one
    ``output_attentions=True`` forward on a fixed probe batch every that-many
    training logs and records per-layer attention entropy and max attention
    probability — the exact collapse signal SDPA hides.

    Metrics are emitted under the ``diag/`` prefix through ``accelerator.log`` on
    the training-loss log cadence (eval-only logs are skipped). Hooks compute
    only device-side RMS reductions and store the latest scalar per module; the
    single host sync happens when metrics are emitted. Under ``torch.compile``
    the inner hooks may cause graph breaks, so run the diagnostic with
    ``train.compile=false``.
    """

    def __init__(self, *, attention_entropy_every: int = 0) -> None:
        if attention_entropy_every < 0:
            raise ValueError(
                f"attention_entropy_every must be >= 0, got {attention_entropy_every}"
            )
        self.attention_entropy_every = attention_entropy_every
        self._handles: list = []
        self._residual: dict[int, torch.Tensor] = {}
        self._q: dict[int, torch.Tensor] = {}
        self._k: dict[int, torch.Tensor] = {}
        self._logit: torch.Tensor | None = None
        self._probe_batch: dict[str, torch.Tensor] | None = None
        self._log_count = 0
        self._entropy_disabled = False

    # -- lifecycle ----------------------------------------------------------

    def on_train_start(self, trainer: Trainer) -> None:
        model = trainer.accelerator.unwrap_model(trainer.model)
        self._register_hooks(model)
        if self.attention_entropy_every > 0:
            self._probe_batch = self._capture_probe_batch(trainer)

    def on_log(self, trainer: Trainer, metrics: dict[str, float], step: int) -> None:
        # Fire only on training-step logs, not eval-only emissions, so the diag
        # cadence tracks train logging.
        if "train/loss" not in metrics:
            return
        self._log_count += 1

        diag: dict[str, float] = {}
        self._emit_rms(diag, "diag/residual_rms", self._residual)
        self._emit_rms(diag, "diag/q_rms", self._q)
        self._emit_rms(diag, "diag/k_rms", self._k)
        if self._logit is not None:
            diag["diag/logit_rms"] = float(self._logit)
        grad_norm = getattr(trainer, "_last_grad_norm", None)
        if grad_norm is not None:
            diag["diag/grad_norm"] = float(grad_norm)

        if (
            self.attention_entropy_every > 0
            and not self._entropy_disabled
            and self._log_count % self.attention_entropy_every == 0
        ):
            self._emit_entropy(trainer, diag)

        if diag:
            trainer.accelerator.log(diag, step=step)

    def on_train_end(self, trainer: Trainer) -> None:
        for handle in self._handles:
            handle.remove()
        self._handles.clear()

    # -- hook wiring --------------------------------------------------------

    def _register_hooks(self, model: nn.Module) -> None:
        """Attach forward hooks to blocks, QK norms, and the readout decoder."""
        for name, module in model.named_modules():
            match = _LAYER_INDEX_RE.search(name)
            idx = int(match.group(1)) if match is not None else None
            if type(module).__name__ == "OplmBlock" and idx is not None:
                self._handles.append(module.register_forward_hook(self._block_hook(idx)))
            elif name.endswith(".attention.q_norm") and idx is not None:
                self._handles.append(module.register_forward_hook(self._store_hook(self._q, idx)))
            elif name.endswith(".attention.k_norm") and idx is not None:
                self._handles.append(module.register_forward_hook(self._store_hook(self._k, idx)))
            elif name.endswith("lm_head.decoder"):
                self._handles.append(module.register_forward_hook(self._logit_hook()))

    def _block_hook(self, idx: int):  # noqa: ANN202 - torch hook closure
        store = self._residual

        def hook(_module: nn.Module, _inputs: object, output: object) -> None:
            # OplmBlock returns a tuple; the residual-stream state is element 0.
            tensor = output[0] if isinstance(output, tuple) else output
            if isinstance(tensor, torch.Tensor):
                store[idx] = _rms(tensor)

        return hook

    @staticmethod
    def _store_hook(store: dict[int, torch.Tensor], idx: int):  # noqa: ANN205 - hook closure
        def hook(_module: nn.Module, _inputs: object, output: object) -> None:
            if isinstance(output, torch.Tensor):
                store[idx] = _rms(output)

        return hook

    def _logit_hook(self):  # noqa: ANN202 - torch hook closure
        def hook(_module: nn.Module, _inputs: object, output: object) -> None:
            if isinstance(output, torch.Tensor):
                self._logit = _rms(output)

        return hook

    # -- emission -----------------------------------------------------------

    @staticmethod
    def _emit_rms(diag: dict[str, float], prefix: str, store: dict[int, torch.Tensor]) -> None:
        """Reduce a per-layer RMS map to max / mean / argmax-layer / final-layer."""
        if not store:
            return
        layers = sorted(store)
        values = torch.stack([store[i] for i in layers])
        diag[f"{prefix}/max"] = float(values.max())
        diag[f"{prefix}/mean"] = float(values.mean())
        diag[f"{prefix}/argmax_layer"] = float(layers[int(values.argmax())])
        diag[f"{prefix}/final_layer"] = float(values[-1])

    @staticmethod
    def _capture_probe_batch(trainer: Trainer) -> dict[str, torch.Tensor] | None:
        """Grab one fixed batch (a fresh iterator; the train iterator is untouched)."""
        try:
            batch = next(iter(trainer.dataloader))
        except (StopIteration, TypeError, KeyError):
            logger.warning("stability entropy probe: could not capture a batch; disabling it")
            return None
        device = trainer.accelerator.device
        return {
            key: batch[key].to(device)
            for key in ("input_ids", "attention_mask")
            if key in batch
        }

    def _emit_entropy(self, trainer: Trainer, diag: dict[str, float]) -> None:
        """Run one output_attentions forward on the probe batch; record entropy stats."""
        if self._probe_batch is None or "input_ids" not in self._probe_batch:
            return
        model = trainer.accelerator.unwrap_model(trainer.model)
        was_training = model.training
        model.eval()
        try:
            with torch.no_grad():
                outputs = model(
                    input_ids=self._probe_batch["input_ids"],
                    attention_mask=self._probe_batch.get("attention_mask"),
                    output_attentions=True,
                )
            attentions = getattr(outputs, "attentions", None)
            entropies: list[torch.Tensor] = []
            max_probs: list[torch.Tensor] = []
            for attn in attentions or ():
                if attn is None:
                    continue
                # attn: (B, H, T, T) fp32, softmaxed over keys.
                p = attn.detach().float().clamp_min(1e-12)
                entropies.append(-(p * p.log()).sum(-1).mean())
                max_probs.append(p.max())
            if entropies:
                ent = torch.stack(entropies)
                diag["diag/attn_entropy/mean"] = float(ent.mean())
                diag["diag/attn_entropy/min"] = float(ent.min())
                diag["diag/attn_max_prob/max"] = float(torch.stack(max_probs).max())
        except Exception as exc:  # noqa: BLE001 - diagnostics must never kill training
            logger.warning("stability entropy probe failed; disabling it: %s", exc)
            self._entropy_disabled = True
        finally:
            if was_training:
                model.train()

